enum Channel {
  CHANNEL_UNSPECIFIED = 0;   // what a reader sees when the writer didn't send it
  CHANNEL_CARD_PRESENT = 1;
  CHANNEL_ECOMMERCE = 2;
}

message Authorization {
  // fields 1 to 5 as before
  string channel = 6;          // still written, still read by old services
  Channel channel_type = 7;    // new
}

// subgoal: read the new field, fall back to the old one
fun channelOf(a: Authorization): Channel =
    if (a.channelType != Channel.CHANNEL_UNSPECIFIED) a.channelType
    else when (a.channel.lowercase()) {
        "card", "card-present" -> Channel.CHANNEL_CARD_PRESENT
        "web", "ecommerce" -> Channel.CHANNEL_ECOMMERCE
        else -> Channel.CHANNEL_UNSPECIFIED
    }

// subgoal: retire the old field for good
message Authorization {
  reserved 6;
  reserved "channel";
  Channel channel_type = 7;
}

